            switch (sector) {
                case 0:
                    set(_v, t, p);
                    break;
                case 1:
                    set(q, _v, p);
                    break;
                case 2:
                    set(p, _v, t);
                    break;
                case 3:
                    set(p, q, _v);
                    break;
                case 4:
                    set(t, p, _v);
                    break;
                default:
                    set(_v, p, q);
            }

            return [ r, g, b ];
