	            selectionLimit: 0,
	            selectedIndex: null,
	            selectedValue: null,
	            value: null,
	            placeholder: null,
	            disabled: false,
	            contentType: 'text', // No I18N
	            template: null,
	            arrowIconClass: '',
	            arrowSVGIconId: '',
	            selectOnCharPress: true,
	            // className: null
	            // zclassName: null,
	            /* API TO ARRIVE */
	            sort: false,
	            sortBy: null,
	            sortOrder: 'asc', // No I18N
	            width: null,
	            isLabelHTMLEncoded: false,
	            cacheData: true,
	            isResponseFiltered: true,
	            serverSearch: false,
	            acceptNewValues: false,
	            newValuePattern: false,
