	            CONTAINER: 'zselectbox', // No I18N
	            ICON: 'zselectbox__icon', // No I18N
	            ICONTEXT: 'zselectbox--icontext', // No I18N
	            ICONONLY: 'zselectbox--icononly', // No I18N
	            TEXT: 'zselectbox__text', // No I18N
