		    let rgbObj = this._colorInstance.getObject();
		    this._setGradientColors(gradient, [ `rgba(${rgbObj.r}, ${rgbObj.g}, ${rgbObj.b}, 0)`, `rgb(${rgbObj.r} ,${rgbObj.g} ,${rgbObj.b})` ]);
